<script setup>
import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import PageHeader from '../../components/common/PageHeader.vue';import MaterialSwatch from '../../components/common/MaterialSwatch.vue';import {createDraft} from '../../utils/customize.js'
const form=reactive(createDraft()),formRef=ref(),router=useRouter();const rules={contact:[{required:true,message:'请填写联系人',trigger:'blur'}],phone:[{required:true,message:'请填写联系电话',trigger:'blur'}],budget:[{required:true,message:'请选择预算范围',trigger:'change'}]};const materialOptions=[['暖白烤漆','#eee9df'],['深胡桃木','#4b3328'],['浅橡木','#b99b73'],['米色岩板','#d3c4aa']];function toggle(x){const i=form.materials.indexOf(x);i<0?form.materials.push(x):form.materials.splice(i,1)};async function next(){await formRef.value.validate();sessionStorage.setItem('customizeDraft',JSON.stringify(form));router.push('/customize/confirm')};function upload(){form.floorPlan='户型图_示例.pdf';ElMessage.success('户型文件已添加')}
</script>
<template><div class="page-shell"><div class="container form-page"><PageHeader title="在线定制" description="告诉我们空间现状与生活习惯，设计师将据此准备初步沟通方案。" :breadcrumbs="['首页','在线定制']"/><el-form ref="formRef" :model="form" :rules="rules" label-width="110px"><section class="form-section"><h2>联系人信息</h2><div class="form-grid"><el-form-item label="联系人" prop="contact"><el-input v-model="form.contact" placeholder="请输入称呼"/></el-form-item><el-form-item label="联系电话" prop="phone"><el-input v-model="form.phone" placeholder="用于设计师联系"/></el-form-item></div></section><section class="form-section"><h2>空间与尺寸</h2><div class="form-grid"><el-form-item label="定制空间"><el-select v-model="form.space"><el-option v-for="x in ['厨房','餐厅','客厅','卧室','玄关','书房','全屋']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="房屋类型"><el-select v-model="form.houseType" placeholder="请选择"><el-option v-for="x in ['新房毛坯','精装改造','旧房翻新']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="空间尺寸" class="full"><div class="dimension-row"><el-input-number v-model="form.dimensions.length" :min="0" placeholder="长"/><span>×</span><el-input-number v-model="form.dimensions.width" :min="0" placeholder="宽"/><span>×</span><el-input-number v-model="form.dimensions.height" :min="0" placeholder="高"/><span>mm</span></div></el-form-item><el-form-item label="户型图" class="full"><el-button plain @click="upload">选择文件</el-button><span class="upload-name">{{form.floorPlan||'支持图片或 PDF，静态演示不上传服务器'}}</span></el-form-item></div></section><section class="form-section"><h2>风格与材料</h2><el-form-item label="风格偏好"><el-radio-group v-model="form.style"><el-radio-button v-for="x in ['现代欧式','法式简约','现代原木','极简']" :key="x" :value="x">{{x}}</el-radio-button></el-radio-group></el-form-item><el-form-item label="材料偏好"><div class="swatch-row"><MaterialSwatch v-for="x in materialOptions" :key="x[0]" :label="x[0]" :color="x[1]" :active="form.materials.includes(x[0])" @click="toggle(x[0])"/></div></el-form-item></section><section class="form-section"><h2>预算与交付</h2><div class="form-grid"><el-form-item label="预算范围" prop="budget"><el-select v-model="form.budget" placeholder="请选择"><el-option v-for="x in ['3 万元以内','3–5 万元','5–8 万元','8–12 万元','12 万元以上']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="期望交付"><el-date-picker v-model="form.deliveryDate" type="date" placeholder="选择日期" style="width:100%"/></el-form-item><el-form-item label="补充说明" class="full"><el-input v-model="form.description" type="textarea" :rows="4" placeholder="描述收纳习惯、家庭成员或需要重点解决的问题"/></el-form-item></div></section><div class="form-actions"><el-button @click="$router.push('/home')">暂不填写</el-button><el-button type="primary" @click="next">确认需求</el-button></div></el-form></div></div></template>
<style scoped>.form-page{max-width:960px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.full{grid-column:1/-1}.dimension-row,.swatch-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.upload-name{margin-left:12px;color:var(--c-muted)}.form-actions{display:flex;justify-content:flex-end;gap:12px;padding-top:24px;border-top:1px solid var(--c-border)}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.dimension-row{align-items:stretch;flex-direction:column}.dimension-row span{display:none}.upload-name{display:block;margin:8px 0}.form-actions>*{flex:1}}</style>
